import{_ as s,C as i,o as n,c as t,E as r,a2 as o}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"数字员工每日观察 002 — 控制面与工作 Runtime 是两个不同系统","description":"","frontmatter":{"title":"数字员工每日观察 002 — 控制面与工作 Runtime 是两个不同系统","date":"2026-08-02","column":"digital-employee","category":"daily","summary":"Workday、ServiceNow 与 Microsoft 正在把跨 Agent 治理和具体工作执行拆成两个层次，数字员工平台因此需要控制面与工作 Runtime。","cover":"/assets/covers/control-plane-work-runtime-cover-v2.jpg","sources":["Workday Agent System of Record and Agent Gateway","ServiceNow AI Control Tower and Autonomous Workforce","Microsoft Agent 365"],"outline":"deep"},"headers":[],"relativePath":"zh/digital-employee/2026-08-02-control-plane-work-runtime.md","filePath":"zh/digital-employee/2026-08-02-control-plane-work-runtime.md","lastUpdated":1787407830000}'),l={name:"zh/digital-employee/2026-08-02-control-plane-work-runtime.md"};function p(c,e,h,d,k,u){const a=i("ArticleCover");return n(),t("div",null,[r(a,{image:"/assets/covers/control-plane-work-runtime-cover-v2.jpg",kicker:"数字员工 · 每日观察 002",title:"控制面与工作 Runtime 是两个不同系统",summary:"一个系统管理身份、所有权与准入，另一个系统推进具体工作；两者必须分开建模，并通过有边界的契约连接。",version:"DD002",status:"Research Note · 2026-08-02",languageHref:"/en/digital-employee/2026-08-02-control-plane-work-runtime",languageLabel:"English"}),e[0]||(e[0]=o(`<h1 id="数字员工每日观察-002-—-控制面与工作-runtime-是两个不同系统" tabindex="-1">数字员工每日观察 002 — 控制面与工作 Runtime 是两个不同系统 <a class="header-anchor" href="#数字员工每日观察-002-—-控制面与工作-runtime-是两个不同系统" aria-label="Permalink to &quot;数字员工每日观察 002 — 控制面与工作 Runtime 是两个不同系统&quot;">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>当前企业产品正在逐渐形成两类不同的系统职责。</p><p>第一类是<strong>控制面</strong>：负责跨 Agent 的资产清单、身份、Owner、政策、访问、生命周期、风险、成本、可观测与合规。</p><p>第二类是<strong>工作 Runtime</strong>：负责接收工作、制定计划、执行工作流节点、调用工具、维护状态、升级、恢复、产出证据，以及判断工作是否完成。</p><p>Workday Agent System of Record、ServiceNow AI Control Tower 和 Microsoft Agent 365 更强地覆盖第一层；ServiceNow Autonomous Workforce 以及现有 Agent Runtime 则展示了第二层的一部分。</p><p>本次研究判断是：</p><blockquote><p>数字员工平台必须同时具备控制面与工作 Runtime，但二者必须分开建模。治理资产清单不能替代工作执行，Agent Runtime 也不能替代组织治理。</p></blockquote><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><h3 id="入选的官方资料" tabindex="-1">入选的官方资料 <a class="header-anchor" href="#入选的官方资料" aria-label="Permalink to &quot;入选的官方资料&quot;">​</a></h3><ol><li><strong>Workday Agent System of Record 与 Agent Gateway</strong>：入选原因是其跨 Provider Registry、生命周期、身份权限、交互计量、分析、成本与问责模型。</li><li><strong>ServiceNow AI Control Tower</strong>：入选原因是它把跨 Agent、模型、Workflow、Identity 和 MCP Server 的治理明确拆分为 Discover、Observe、Govern、Secure、Measure。</li><li><strong>ServiceNow Autonomous Workforce</strong>：入选原因是它把 AI Specialist 接入确定性工作流、政策、Trace、人工升级和端到端执行。</li><li><strong>Microsoft Agent 365</strong>：入选原因是它提供 Registry、Agent Map、生命周期、Owner、访问治理、安全和合规能力，并覆盖第一方与外部 Agent。</li></ol><p>这些资料可以用于判断产品架构和厂商方向，但不能单独证明某种架构对所有组织都足够，也不能证明其成本结构适合中小企业。</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><h3 id="_1-企业治理正在跨越单一-provider" tabindex="-1">1. 企业治理正在跨越单一 Provider <a class="header-anchor" href="#_1-企业治理正在跨越单一-provider" aria-label="Permalink to &quot;1. 企业治理正在跨越单一 Provider&quot;">​</a></h3><p>Workday 表示第一方与第三方 Agent 都可以进入 Agent System of Record，并通过 Agent Gateway 被管理与计量。Microsoft Agent Registry 可以同步外部环境。ServiceNow AI Control Tower 则盘点第一方和第三方 Agent、模型、Identity、Workflow 和 MCP Server。</p><p>因此，治理层正在位于单一 Agent 框架或模型 Provider 之上。</p><h3 id="_2-控制面管理生命周期与风险-不管理具体任务逻辑" tabindex="-1">2. 控制面管理生命周期与风险，不管理具体任务逻辑 <a class="header-anchor" href="#_2-控制面管理生命周期与风险-不管理具体任务逻辑" aria-label="Permalink to &quot;2. 控制面管理生命周期与风险，不管理具体任务逻辑&quot;">​</a></h3><p>三类平台共同覆盖的控制面能力包括：</p><ul><li>注册与发现；</li><li>Owner 分配；</li><li>身份与权限；</li><li>激活、阻断、停用和退役；</li><li>政策与合规；</li><li>Runtime 监控；</li><li>成本与价值度量；</li><li>Inventory 与关系图。</li></ul><p>它们回答的是：部署了什么、谁负责、能访问什么、是否健康、是否应继续运行。</p><p>但它们没有完整回答：一个 WorkOrder 应如何拆分、执行、恢复、验证和关闭。</p><h3 id="_3-工作执行需要确定性的工作流结构" tabindex="-1">3. 工作执行需要确定性的工作流结构 <a class="header-anchor" href="#_3-工作执行需要确定性的工作流结构" aria-label="Permalink to &quot;3. 工作执行需要确定性的工作流结构&quot;">​</a></h3><p>ServiceNow 明确区分概率模型与企业对确定性结果的要求。其 AI Specialist 通过既有 Workflow 执行，使用组织知识，遵循政策，产生可追踪动作，并在需要人类权威时升级。</p><p>这说明执行层需要的不只是 Agent Identity，还需要状态迁移、Operation Contract、证据、升级、恢复与完成门禁。</p><h3 id="_4-可观测性存在两个层次" tabindex="-1">4. 可观测性存在两个层次 <a class="header-anchor" href="#_4-可观测性存在两个层次" aria-label="Permalink to &quot;4. 可观测性存在两个层次&quot;">​</a></h3><p>控制面观察的是 Fleet 级事实：资产清单、安全姿态、性能、成本和政策一致性。</p><p>工作 Runtime 观察的是 Work 级事实：当前 WorkOrder、活动 Operation、Session 状态、Tool Result、Retry、Checkpoint、Evidence、Review 与 Completion Status。</p><p>如果把二者混为一套无差别日志，运营诊断和治理判断都会更困难。</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><h3 id="建议的两层结构" tabindex="-1">建议的两层结构 <a class="header-anchor" href="#建议的两层结构" aria-label="Permalink to &quot;建议的两层结构&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数字员工控制面</span></span>
<span class="line"><span>  身份</span></span>
<span class="line"><span>  岗位与 Owner</span></span>
<span class="line"><span>  Registry</span></span>
<span class="line"><span>  权限与访问政策</span></span>
<span class="line"><span>  Provider 与 Tool Binding</span></span>
<span class="line"><span>  生命周期</span></span>
<span class="line"><span>  Fleet Health</span></span>
<span class="line"><span>  成本与评估</span></span>
<span class="line"><span>  合规与审计视图</span></span>
<span class="line"><span></span></span>
<span class="line"><span>数字员工工作 Runtime</span></span>
<span class="line"><span>  WorkOrder Intake</span></span>
<span class="line"><span>  Plan 与 Workflow</span></span>
<span class="line"><span>  Operation Node</span></span>
<span class="line"><span>  Session 与 Tool</span></span>
<span class="line"><span>  Checkpoint 与 Retry</span></span>
<span class="line"><span>  Escalation 与 Recovery</span></span>
<span class="line"><span>  Evidence Production</span></span>
<span class="line"><span>  Review 与 Completion Gate</span></span></code></pre></div><p>控制面判断某个执行身份是否被允许、是否适合继续运行；工作 Runtime 决定一项具体工作怎样推进。</p><h3 id="为什么任何一层都不能替代另一层" tabindex="-1">为什么任何一层都不能替代另一层 <a class="header-anchor" href="#为什么任何一层都不能替代另一层" aria-label="Permalink to &quot;为什么任何一层都不能替代另一层&quot;">​</a></h3><p>只有 Registry、没有 Runtime，可以列出和治理 Agent，却不能可靠完成组织工作。</p><p>只有 Runtime、没有控制面，可以执行任务，却无法回答 Owner、生命周期、Agent Sprawl、访问、成本、政策和退役等企业问题。</p><p>因此：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>受治理的数字员工平台</span></span>
<span class="line"><span>= 控制面</span></span>
<span class="line"><span>+ 工作 Runtime</span></span>
<span class="line"><span>+ 二者之间的明确契约</span></span></code></pre></div><h3 id="两层之间的契约最关键" tabindex="-1">两层之间的契约最关键 <a class="header-anchor" href="#两层之间的契约最关键" aria-label="Permalink to &quot;两层之间的契约最关键&quot;">​</a></h3><p>控制面应向 Runtime 下发有边界的执行上下文：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">execution_context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  digital_employee_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  position_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_order_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority_snapshot_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed_tool_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  provider_binding_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cost_policy_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evidence_policy_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  escalation_policy_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>Runtime 应返回结构化事实：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">execution_result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  lifecycle_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tool_and_session_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evidence_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cost_usage_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evaluation_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  completion_judgment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  unresolved_escalations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>这样，即使 Runtime 的实现发生变化，治理层仍然可以保持稳定。</p><h3 id="sme-first-的含义" tabindex="-1">SME-first 的含义 <a class="header-anchor" href="#sme-first-的含义" aria-label="Permalink to &quot;SME-first 的含义&quot;">​</a></h3><p>Workday、ServiceNow 与 Microsoft 都假设企业已经拥有相当重的基础设施。CodeFlowMu 不应在验证一个完整数字员工生命周期之前，先复制一套大型 Control Tower。</p><p>面向中小企业的最小完整系统应包括：</p><ul><li>小型持久 Registry；</li><li>明确 Owner 与 Position；</li><li>Tool / Provider Binding；</li><li>轻量政策检查；</li><li>Runtime Health 与 Recovery View；</li><li>Evidence 与 Cost Projection；</li><li>人类保留激活、例外和发布权威。</li></ul><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>本研究笔记不直接修改 TMPA 正式出版物。它提供的研究输入是：治理记录与运营执行应分层，同时必须通过 Reference 保持可重建关系。</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>架构应明确把 Control Plane 与 Work Runtime 定义为两个层次，并通过稳定契约连接。Position 与 Lifecycle 主要属于控制面；WorkOrder 执行与 Evidence Production 主要属于 Runtime。</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu 已经包含大量 Work Runtime 能力：</p><ul><li>PM 编排；</li><li>Task 与 Report 生命周期；</li><li>Session 管理；</li><li>Skill 与 Tool；</li><li>Retry、HOLD、Wake 与 Recovery；</li><li>FCoP 协作；</li><li>Evidence 与 Completion Gate。</li></ul><p>下一步安全做法不是替换现有 Runtime，而是在其上方增加轻量、只读的 Control Plane Projection：</p><ol><li>把当前 Open Dev Team 注册为第一个数字员工；</li><li>注册 PM、DEV、QA、OPS 的岗位定义；</li><li>展示 Provider、Tool、Session、Lifecycle、Cost 和 Health Binding；</li><li>验证期间保持现有 Runtime 行为不变；</li><li>后续再把政策检查放到 WorkOrder Admission 和 Tool Invocation 边界。</li></ol><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><ol><li>定义最小 Control Plane 数据模型。</li><li>把现有 CodeFlowMu Runtime 事实逐项归类为 Control Plane 或 Work Runtime。</li><li>定义 Registry 到 WorkOrder 的 Admission Contract。</li><li>定义审计和回放必须保存的 Policy Snapshot。</li><li>比较 Fleet-level Observability 与 Task-level Observability。</li><li>使用一个非开发类数字员工案例验证两层模型。</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Workday，<strong>Agent System of Record</strong>：<a href="https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html</a></li><li>Workday，<strong>The Workday Agent System of Record Is Now Generally Available</strong>：<a href="https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html" target="_blank" rel="noreferrer">https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html</a></li><li>Workday，<strong>CIO Buyer Guide to an AI-ready HR and Finance Platform</strong>：<a href="https://www.workday.com/en-us/topics/it/cio-buyers-guide.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/topics/it/cio-buyers-guide.html</a></li><li>ServiceNow，<strong>AI Control Tower</strong>：<a href="https://www.servicenow.com/products/ai-control-tower.html" target="_blank" rel="noreferrer">https://www.servicenow.com/products/ai-control-tower.html</a></li><li>ServiceNow，<strong>ServiceNow expands AI Control Tower</strong>：<a href="https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-expands-AI-Control-Tower-to-discover-observe-govern-secure-and-measure-AI-deployed-across-any-system-in-the-enterprise/default.aspx" target="_blank" rel="noreferrer">https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-expands-AI-Control-Tower-to-discover-observe-govern-secure-and-measure-AI-deployed-across-any-system-in-the-enterprise/default.aspx</a></li><li>ServiceNow，<strong>ServiceNow launches Autonomous Workforce that thinks and acts</strong>：<a href="https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx" target="_blank" rel="noreferrer">https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx</a></li><li>Microsoft，<strong>Microsoft Agent 365</strong>：<a href="https://www.microsoft.com/microsoft-agent-365" target="_blank" rel="noreferrer">https://www.microsoft.com/microsoft-agent-365</a></li><li>Microsoft Learn，<strong>Microsoft Agent 365 overview</strong>：<a href="https://learn.microsoft.com/en-us/microsoft-agent-365/overview" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/overview</a></li><li>Microsoft Learn，<strong>Registry sync in the Microsoft 365 agent registry</strong>：<a href="https://learn.microsoft.com/en-us/microsoft-agent-365/admin/agent-registry" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/admin/agent-registry</a></li><li>Microsoft Learn，<strong>Manage the agent lifecycle</strong>：<a href="https://learn.microsoft.com/en-us/agents/center-of-excellence/agent-lifecycle" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/agents/center-of-excellence/agent-lifecycle</a></li></ol>`,61))])}const f=s(l,[["render",p]]);export{m as __pageData,f as default};
